mapper.select:
SELECT b_id bId, contact_id contactId, `name`, tel, out_id outId, operate
FROM business_outgoing_unit_contact
WHERE b_id = #{bId} AND operate = #{operate}

select t.contact_id,t.contact_id contactId,t.create_time,t.create_time createTime,t.name,t.tel,t.out_id,t.out_id
outId,t.status_cd,t.status_cd statusCd,t.b_id,t.b_id bId
from outgoing_unit_contact t
where 1 =1

    and t.contact_id= #{contactId}


    and t.create_time= #{createTime}


    and t.name= #{name}


    and t.tel= #{tel}


    and t.out_id= #{outId}


    and t.status_cd= #{statusCd}


    and t.b_id= #{bId}

order by t.create_time desc

    limit #{page}, #{row}

