update outgoing_unit_contact t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.create_time= #{createTime}


    , t.name= #{name}


    , t.tel= #{tel}


    , t.out_id= #{outId}

where 1=1

    and t.contact_id= #{contactId}


    and t.b_id= #{bId}

